import request from '@/hooks/useHttp'

export function getWebSearchConfig(params) {
  return request({
    url: '/plugin-param/web-search/list',
    method: 'get',
    params
  })
}

export function setWebSearchConfig(data) {
  return request({
    url: `/plugin-param/web-search/update/${data.session_id}`,
    method: 'put',
    data
  })
}
