<script setup>
import useWebSearchStore from '@/stores/websearch'
import { getEmbedModels } from '@/services/knowledge'
import * as yup from 'yup'
import { i18nRender } from '@/locales'
import { useForm } from 'vee-validate'
import { useToast } from 'primevue/usetoast'
import { ref } from 'vue'
import Markdown from '@/views/chat/components/Markdown.vue'
import { useWebview } from '@/composables/useWebview'

const { openExternalLink } = useWebview()

const toast = useToast()

const props = defineProps({
  pluginId: {
    type: [String, Number],
    default: 0
  },
  initParams: {
    type: Object,
    default: () => null
  },
  isSettingDefault: {
    type: Boolean,
    default: false
  }
})

const modelList = ref([])

const windowsOllamaConfig = `
  ### 推荐下载模型
\`\`\`bash
  ollama run nomic-embed-text
\`\`\`
  ### ollama安装流程

  #### 步骤 1：在本地安装并启动 Ollama

  确保您的计算机上已安装 Ollama。如果尚未安装，请访问[官方网站](https://ollama.com/download) 进行下载和安装。

  #### 步骤 2：配置 Ollama 的跨域访问

  由于浏览器安全限制，您需要配置 Ollama 的跨域访问权限，以确保其正常运行。

  1. 在 Windows 上，打开**控制面板**，并编辑系统环境变量。
  2. 创建一个新的环境变量，命名为\`OLLAMA_ORIGINS\`（适用于当前用户）。
  3. 将该变量的值设置为\`*\`，然后点击 **OK/Apply**以保存更改。

  #### 步骤 3：拉取最新的模型

  在终端中运行以下命令下载模型：
\`\`\`bash
ollama pull nomic-embed-text
\`\`\`

  ### 其他Embedding模型推荐
\`\`\`bash
ollama pull mxbai-embed-large
ollama pull snowflake-arctic-embed
ollama pull granite-embedding
\`\`\`

  `

const visible = ref(false)

const showhasnoflag = ref(false)

const needaddembed = `
请前往 ⚙️<strong>【设置】</strong>-<strong>【嵌入模型】</strong> 中，进行模型选择与设置
`
async function getModels() {
  try {
    const res = await getEmbedModels()
    modelList.value = res.resData

    if (!modelList.value?.length) {
      // 使用可选链操作符简化判断
      showhasnoflag.value = true
    } else {
      wsForm.embedding_model_id = modelList.value[0].id
    }
  } catch (error) {
    console.error('获取模型失败:', error)
    showhasnoflag.value = true
  }
}

getModels()

const formatOptionLabel = (option) => {
  if (!option) return ''
  return `${option.cn_name} : ${option.name}`
}

const style_search = ref('serper')

const searxngInstances = ref([
  'https://search.cloakpanda.com/',
  'https://searx.foobar.vip/',
  'https://searxng.world/',
  'https://search.ipv6s.net/',
  'https://searx.oloke.xyz/',
  'https://search.librenode.com/',
  'https://search.catboy.house/',
  'https://search.080609.xyz/',
  'https://search.nordh.tech/',
  'https://suche.dasnetzundich.de/',
  'https://searxng.website/',
  'https://searxng.biz/',
  'https://searxng.deliberate.world/',
  'https://searx.mbuf.net/',
  'https://search.url4irl.com/',
  'https://searx.cespedes.fr/',
  'https://metacat.online/',
  'https://search.mrblake.cc/'
])

const schema = computed(() =>
  yup.object({
    style_search: yup.string().required(i18nRender('lang.noEmpty')),
    web_api_key:
      style_search?.value === 'bing_bs4' || style_search?.value === 'searxng'
        ? null
        : yup
            .string()
            .required(i18nRender('lang.noEmpty'))
            .label(style_search?.value === 'serper' ? 'Serper API Key' : 'Bocha API Key'),
    searxng_url: style_search?.value === 'searxng' ? yup.string().required(i18nRender('lang.noEmpty')) : null,
    embedding_model_id: yup.string().required(i18nRender('lang.noEmpty')).label(i18nRender('lang.embedding_model_id')),
    retrieve_topk: yup.number().required(i18nRender('lang.noEmpty'))
  })
)

const { defineField, handleSubmit, errors } = useForm({
  validationSchema: schema,
  initialValues: {
    style_search: 'serper',
    web_api_key: '',
    embedding_model_id: '',
    retrieve_topk: 3,
    searxng_url: ''
  }
})

style_search.value = defineField('style_search')[0]

const wsForm = reactive({
  web_api_key: defineField('web_api_key')[0],
  searxng_url: defineField('searxng_url')[0],
  embedding_model_id: defineField('embedding_model_id')[0],
  retrieve_topk: 3,
  template: ''
})

const WebSearchStore = useWebSearchStore()

async function initWsConfig() {
  if (props.isSettingDefault) {
    style_search.value = props.initParams.style_search
    wsForm.web_api_key = props.initParams.web_api_key
    wsForm.embedding_model_path = props.initParams.embedding_model_path
    wsForm.retrieve_topk = props.initParams.retrieve_topk
    wsForm.template = props.initParams.template
    wsForm.searxng_url = props.initParams.searxng_url
    return props.initParams
  } else {
    const modelParams = await WebSearchStore.getParams(props.pluginId)
    style_search.value = modelParams.style_search
    wsForm.web_api_key = modelParams.web_api_key
    wsForm.embedding_model_id = modelParams.embedding_model_id
    wsForm.retrieve_topk = modelParams.retrieve_topk
    wsForm.template = modelParams.template
    wsForm.searxng_url = modelParams.searxng_url
  }
}

initWsConfig()

const searchType = ref([
  'serper',
  'bocha',
  // 'bing_api',
  'bing_bs4',
  'searxng'
])

const submit = handleSubmit(() => {
  WebSearchStore.setParam({
    style_search: style_search.value,
    web_api_key: wsForm.web_api_key,
    searxng_url: wsForm.searxng_url,
    embedding_model_id: wsForm.embedding_model_id,
    retrieve_topk: wsForm.retrieve_topk,
    template: wsForm.template,
    plugin_id: props.pluginId
  }).then(() => {
    initWsConfig()
    toast.add({ severity: 'success', summary: i18nRender('lang.saveSuccess'), life: 3000 })
  })
})

const exposeSubmit = handleSubmit(() => {
  return {
    style_search: style_search.value,
    web_api_key: wsForm.web_api_key,
    searxng_url: wsForm.searxng_url,
    embedding_model_id: wsForm.embedding_model_id,
    retrieve_topk: wsForm.retrieve_topk,
    template: wsForm.template,
    plugin_id: props.pluginId
  }
})

defineExpose({
  exposeSubmit
})

const SerperLink = () => {
  const url = 'https://serper.dev'
  openExternalLink(url) //  使用封装函数
}

const BochaLink = () => {
  const url = 'https://open.bochaai.com/'
  openExternalLink(url) //  使用封装函数
}
</script>

<template>
  <div class="space-y-4 flex flex-col w-full items-center tabs-item">
    <div class="w-full flex flex-col items-start justify-between">
      <div class="label text-slate-500 dark:text-slate-400 font-semibold">{{ $t('lang.searchType') }}</div>
      <div class="flex w-full flex-col items-start justify-start mt-1">
        <Dropdown :invalid="!!errors.style_search" class="w-full" :options="searchType" v-model="style_search"></Dropdown>
        <small class="text-red-400 mt-1">{{ errors.style_search }}</small>
      </div>
    </div>
    <div class="w-full flex flex-col items-start justify-between" v-if="style_search !== 'bing_bs4' && style_search !== 'searxng'">
      <div class="label text-slate-500 dark:text-slate-400 font-semibold">
        {{ style_search === 'serper' ? 'Serper API Key' : 'Bocha API Key' }}
        <a
          target="_blank"
          class="py-0.5 text-sm font-medium text-violet-500 underline decoration-zinc-500/20 underline-offset-4 hover:opacity-90"
          href="#"
          @click.stop.prevent="style_search === 'serper' ? SerperLink() : BochaLink()"
        >
          点击获取
        </a>
      </div>
      <div class="flex w-full flex-col items-start justify-start mt-1">
        <InputText :invalid="!!errors.web_api_key" class="w-full border" type="text" v-model="wsForm.web_api_key" />
        <small class="text-red-400 mt-1">{{ errors.web_api_key }}</small>
      </div>
    </div>
    <div class="w-full flex flex-col items-start justify-between" v-if="style_search === 'searxng'">
      <div class="label text-slate-500 dark:text-slate-400 font-semibold">SearXNG在线实例</div>
      <div class="flex w-full flex-col items-start justify-start mt-1">
        <Dropdown :invalid="!!errors.searxng_url" class="w-full" :options="searxngInstances" v-model="wsForm.searxng_url"></Dropdown>
        <small class="text-red-400 mt-1">{{ errors.searxng_url }}</small>
      </div>
    </div>
    <div class="w-full flex flex-col items-start justify-between">
      <div class="label shrink-0 w-48 text-slate-500 dark:text-slate-400 font-semibold">
        {{ $t('lang.embeddingModelPath') }}
        <Button text icon="pi pi-question-circle" @click="visible = true" class="h-5 !px-2"></Button>
        <!-- <Markdown v-if="visible" :content="windowsOllamaConfig"></Markdown> -->
        <Dialog v-model:visible="visible" header="请使用ollama下载模型" :style="{ width: '800px' }" :modal="true">
          <div class="content-box">
            <Markdown :content="windowsOllamaConfig"></Markdown>
          </div>
        </Dialog>
        <Dialog v-model:visible="showhasnoflag" header="未检测到可使用的【嵌入模型】" :style="{ width: '800px' }" :modal="true">
          <div class="content-box">
            <Markdown :content="needaddembed"></Markdown>
          </div>
        </Dialog>
        <div class="flex w-full flex-col items-start justify-start mt-1">
          <Dropdown
            class="w-full"
            :invalid="!!errors.embedding_model_id"
            :options="modelList"
            v-model="wsForm.embedding_model_id"
            :optionLabel="formatOptionLabel"
            optionValue="id"
          ></Dropdown>
          <small class="text-red-400 mt-1">{{ errors.embedding_model_id }}</small>
        </div>
      </div>
      <div class="w-full flex flex-col items-start justify-between">
        <div class="label shrink-0 w-48 text-slate-500 dark:text-slate-400 font-semibold">
          {{ $t('lang.sourceTopK') }}
        </div>
        <div class="flex w-full flex-row items-center justify-start mt-1 space-x-4">
          <InputNumber class="w-full" inputClass="w-full border" v-model="wsForm.retrieve_topk" :min="1" :max="8" />
        </div>
      </div>
      <div class="w-full flex flex-col items-start justify-between">
        <div class="label shrink-0 w-48 text-slate-500 dark:text-slate-400 font-semibold">
          {{ $t('lang.llmTemplate') }}
        </div>
        <div class="flex flex-row items-center justify-start mt-1 space-x-4">
          <Textarea class="w-full border leading-5" v-model="wsForm.template" rows="3" cols="30" />
        </div>
      </div>
      <Button v-if="!props.isSettingDefault" class="self-end" @click="submit">{{ $t('lang.save') }}</Button>
    </div>
  </div>
</template>

<style scoped lang="scss">
.tabs-item {
  top: 50px;
  width: 260px;
  left: -28px;
  flex-direction: column;
  display: flex;
  align-items: left;
  justify-content: left;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
</style>
