import { getWebSearchConfig, setWebSearchConfig } from '@/services/websearch'
import useChatStore from '@/stores/chat'

const useWebSearchStore = defineStore('webSearch', () => {
  const params = reactive({})

  const ChatStore = useChatStore()

  async function getParams(plugin_id) {
    const { resData } = await getWebSearchConfig({ session_id: ChatStore.currentConversationId, plugin_id })
    params.serper_key = resData.serper_key
    params.web_api_key = resData.web_api_key
    params.url = resData.url
    params.style_search = resData.style_search
    params.embedding_model_path = resData.embedding_model_path
    params.retrieve_topk = resData.retrieve_topk
    params.template = resData.template
    params.searxng_url = resData.searxng_url
    return resData
  }

  const setParam = (_params) => {
    return setWebSearchConfig(Object.assign({}, _params, { session_id: ChatStore.currentConversationId }))
  }

  return {
    params,
    getParams,
    setParam
  }
})

export default useWebSearchStore
